    act(() => {
      channel.emit!({ event: 'Started', data: { contentLength: 100 } });
      channel.emit!({ event: 'Progress', data: { chunkLength: 42 } });
    });
    await waitFor(() => expect(screen.getByText('下载中 42%') !== null).toBe(true));
    expect(screen.queryByText('正在安装…')).toBeNull();

