    expect(screen.getByRole('button', { name: '← 返回列表' }) !== null).toBe(true);
  });

  it('详情态以新 root 重渲染：过渡轮抑制取数（零「新根 + 旧名」误发），replace 导航落 /changes；再入详情恢复 (新root, 新名) 取数', async () => {
